function highlightSite(){const id=hoveredSite||focusedSite||activeSite;for(const entry of markerEntries()){const element=entry.marker.getElement();if(!element)continue;const linked=entry.site.site_id===id;element.classList.toggle('is-related',linked);element.setAttribute('aria-pressed',String(entry.site.site_id===activeSite));entry.marker.setZIndexOffset(linked?1200:0);}}
function hoverSite(id){clearTimeout(hoverTimer);hoveredSite=id;highlightSite();}
function leaveSite(id){clearTimeout(hoverTimer);hoverTimer=setTimeout(()=>{if(hoveredSite===id){hoveredSite='';highlightSite();}},70);}
function stopLabel(entry){return 'SR2T · '+entry.site.profile.name+' · Stop '+entry.stop.number;}
function stopTooltip(entry){const count=C.mappedStops(entry.site,networkMeta?.fingerprint).length;return N('span','',entry.site.profile.name+' · Stop '+entry.stop.number+(count>1?' · '+count+' stops in this site':''));}
function updateStopMarker(entry){const el=entry.marker.getElement();if(!el)return;el.style.setProperty('--sr2t-color',C.colors[entry.site.profile.status]||C.colors.Unknown);el.classList.toggle('is-compact',entry.view==='main'&&map.getZoom()<13);el.setAttribute('aria-label',stopLabel(entry));el.dataset.sr2tSite=entry.site.site_id;el.dataset.sr2tStop=entry.stop.stop_id||entry.stop.number;}
function stopPopup(entry){const box=N('div','sr2t-stop-popup');box.append(N('strong','',entry.site.profile.name),N('p','','Stop '+entry.stop.number+' · '+entry.stop.stop_name));const points=C.mappedStops(entry.site,networkMeta?.fingerprint);if(points.length>1)box.append(P(points.length+' linked stops in this site'),B('Show all stops',()=>{activeSite=entry.site.site_id;highlightSite();map.fitBounds(L.latLngBounds(points.map(p=>p.latlng)).pad(.35),{maxZoom:17,padding:[35,35]});}));box.append(B('Open site profile',()=>{activeSite=entry.site.site_id;highlightSite();open(false,entry.site.site_id);}));L.DomEvent.disableClickPropagation(box);return box;}
