 marker.bindTooltip(()=>stopTooltip(entry),{direction:'top',className:'sr2t-stop-tooltip',opacity:1});
 marker.on('mouseover',()=>hoverSite(entry.site.site_id));marker.on('mouseout',()=>leaveSite(entry.site.site_id));
 marker.on('add',()=>{const element=marker.getElement();element.addEventListener('focus',()=>{focusedSite=entry.site.site_id;highlightSite();});element.addEventListener('blur',()=>{if(focusedSite===entry.site.site_id)focusedSite='';highlightSite();});element.addEventListener('keydown',e=>{if(e.key===' '){e.preventDefault();marker.fire('click');}if(e.key==='Escape'){activeSite='';focusedSite='';hoveredSite='';map.closePopup();highlightSite();}});updateStopMarker(entry);highlightSite();});
